        if (match) {
          runResults.push(parseFloat(match[1].replace(',', '')))
        } else {
          console.log('❌ Failed to parse result')
          runResults.push(0)
        }
      }
    } finally {
      server.kill()
      await sleep(500)
    }

    allRuns.push(runResults)
  }

