    } finally {
      server.kill()
      await sleep(1000)
    }
  } else {
    console.log(`  ⏭️ Skipping endpoint tests for ${name}`)
  }

  // Restore git state
  if (version !== 'current' && needsRestore) {
    await runCommand('git checkout -', HONO_ROOT)
    await runCommand(`git stash pop ${stashRef}`, HONO_ROOT)
  } else if (version !== 'current') {
    await runCommand('git checkout -', HONO_ROOT)
  }

  return appPath
}

